import { readFile, realpath } from "node:fs/promises";
import { basename, dirname, join } from "node:path";
import semver from "semver";

/**
 * What the installed dsh must be for the Web host driver, checked before anything is started: the npm `@deepseek-ai/dsh` the launch runs, at least
 * the version its Web host was probed on, whose generated Remote contracts (`lib/typert.remote-client.d.ts` of each package, "Generated by
 * @deepseek-ai/dsh-typert-generator") still have every endpoint the driver calls with the argument names it sends. The contract is internal and
 * generated, with no compatibility promise: a release that renames an argument is caught here, and the driver uses ACP instead.
 */
export const WEB_HOST_FLOOR = "0.2.2-rc.1";
interface Needed { readonly pkg: string; readonly endpoint: string; readonly args: readonly string[]; readonly feature?: "fork" | "title" | "files" | "list" }
export const WEB_ENDPOINTS: readonly Needed[] = [
  { pkg: "dsh-api-session-controller", endpoint: "session/create", args: ["request"] },
  { pkg: "dsh-api-session-controller", endpoint: "session/follow", args: ["request"] },
  { pkg: "dsh-api-session-controller", endpoint: "session/observeState", args: ["request"] },
  { pkg: "dsh-api-session-controller", endpoint: "session/prompt", args: ["request"] },
  { pkg: "dsh-api-session-controller", endpoint: "session/cancel", args: ["request"] },
  { pkg: "dsh-api-session-controller", endpoint: "session/events", args: ["request"] },
  { pkg: "dsh-api-session-controller", endpoint: "session/modelCatalog", args: [] },
  { pkg: "dsh-api-session-controller", endpoint: "session/selectModel", args: ["request"] },
  { pkg: "dsh-commands", endpoint: "commands/execute", args: ["agentId", "line", "submittedAttachments"] },
  { pkg: "dsh-commands", endpoint: "commands/list", args: ["agentId"] },
  { pkg: "dsh-api-session-controller", endpoint: "session/fork", args: ["request"], feature: "fork" },
  { pkg: "dsh-api-session-controller", endpoint: "session/rename", args: ["request"], feature: "title" },
  { pkg: "dsh-api-session-controller", endpoint: "session/list", args: ["_request"], feature: "list" },
  { pkg: "dsh-client-file-upload", endpoint: "fileUploads/upload", args: ["agentId", "request"], feature: "files" },
];
export type WebFeature = NonNullable<Needed["feature"]>;
export type Preflight = { readonly ok: true; readonly version: string; readonly features: ReadonlySet<WebFeature> } | { readonly ok: false; readonly version: string | null; readonly reason: string };

/** The endpoints a generated Remote contract declares, each with its argument names (`readonly '<endpoint>': TypertRemoteMethod<{ readonly '<arg>': … }`). */
export function declaredEndpoints(text: string): ReadonlyMap<string, readonly string[]> {
  const found = new Map<string, readonly string[]>();
  for (const match of text.matchAll(/readonly '([A-Za-z$][\w$/]*)': TypertRemoteMethod<\{([^}]*)\}/gu))
    found.set(match[1]!, [...match[2]!.matchAll(/readonly '([A-Za-z_$][\w$]*)'\??:/gu)].map(arg => arg[1]!));
  return found;
}
export async function preflight(executable: string): Promise<Preflight> {
  let root: string;
  try {
    const bin = await realpath(executable);
    if (basename(bin) !== "bin.js" || basename(dirname(bin)) !== "lib") return { ok: false, version: null, reason: "启动的 dsh 不是 npm 装的 @deepseek-ai/dsh" };
    root = dirname(dirname(bin));
  } catch { return { ok: false, version: null, reason: "找不到启动的 dsh" }; }
  let version: string;
  try {
    const manifest = JSON.parse(await readFile(join(root, "package.json"), "utf8")) as { name?: unknown; version?: unknown };
    if (manifest.name !== "@deepseek-ai/dsh" || typeof manifest.version !== "string") return { ok: false, version: null, reason: "启动的 dsh 不是 npm 装的 @deepseek-ai/dsh" };
    version = manifest.version;
  } catch { return { ok: false, version: null, reason: "读不到 dsh 的版本" }; }
  if (semver.valid(version) === null || semver.lt(version, WEB_HOST_FLOOR)) return { ok: false, version, reason: "dsh " + version + " 早于试过 Web 宿主的 " + WEB_HOST_FLOOR };
  const contracts = new Map<string, ReadonlyMap<string, readonly string[]> | null>();
  const features = new Set<WebFeature>();
  for (const need of WEB_ENDPOINTS) {
    if (!contracts.has(need.pkg)) {
      let declared: ReadonlyMap<string, readonly string[]> | null = null;
      for (const dir of [join(root, "node_modules", "@deepseek-ai", need.pkg), join(dirname(root), need.pkg)]) {
        try { declared = declaredEndpoints(await readFile(join(dir, "lib", "typert.remote-client.d.ts"), "utf8")); break; } catch { /* the next place */ }
      }
      contracts.set(need.pkg, declared);
    }
    const args = contracts.get(need.pkg)?.get(need.endpoint);
    const same = args !== undefined && args.length === need.args.length && need.args.every(arg => args.includes(arg));
    if (same) { if (need.feature) features.add(need.feature); continue; }
    if (need.feature === undefined) return { ok: false, version, reason: "dsh " + version + " 的 Web 宿主" + (args === undefined ? "没有 " + need.endpoint : "改了 " + need.endpoint + " 的参数") };
  }
  return { ok: true, version, features };
}

/** One YAML scalar: JSON's string form is a valid YAML double-quoted scalar. */
const scalar = (value: string): string => JSON.stringify(value);
export interface PatchParts {
  /** The Hub's tool server for the process's sessions; null: none. `fromProcess` are environment names the dsh process has, read by it (`!!js process.env.X`), so the values are never written. */
  readonly tools: { readonly name: string; readonly command: string; readonly args: readonly string[]; readonly env: Readonly<Record<string, string>>; readonly fromProcess: readonly string[] } | null;
  /** The model a session the process creates starts on (`agent-default-model`); null: dsh's own default. */
  readonly model: { readonly provider: string; readonly model: string; readonly reasoningEffort?: string } | null;
}
/**
 * The `--patch` overlay of the process (dsh: applied after the bundles, the profile's own patch and the home patch; read, never written back):
 * - `config-editor` off: nothing this process does writes the user's profile (without it, `session/selectModel` saves the default model into
 *   `profiles/web/cordis.patch.yml`, seen on 0.2.2-rc.1, and the settings service waits for it and stays off);
 * - the model of the sessions it creates, as their default: no profile write, and a route the Web catalog does not list (the user's own) still runs;
 * - the Hub's MCP server for every session of the process: the per-session entry ACP has (`mcpServers`), here per process, which is one conversation.
 */
export function patchText(parts: PatchParts): string {
  const lines = ["# HarnessHub's overlay for this process only.", "- id: config-editor", "  disabled: true"];
  if (parts.model !== null) {
    lines.push("- id: agent-default-model", "  config:", "    provider: " + scalar(parts.model.provider), "    model: " + scalar(parts.model.model));
    if (parts.model.reasoningEffort !== undefined) lines.push("    reasoningEffort: " + scalar(parts.model.reasoningEffort));
  }
  if (parts.tools !== null) {
    const tools = parts.tools;
    lines.push("- insert:", "    - id: harnesshub-mcp", "      name: '@deepseek-ai/dsh-mcp-client'", "      config:", "        serverName: " + scalar(tools.name), "        transport: stdio",
      "        command: " + scalar(tools.command), "        args: [" + tools.args.map(scalar).join(", ") + "]", "        toolCallTimeoutMs: 600000", "        env:");
    for (const name of tools.fromProcess) if (/^[A-Z][A-Z0-9_]*$/u.test(name)) lines.push("          " + name + ": !!js process.env." + name);
    for (const [name, value] of Object.entries(tools.env)) if (/^[A-Z][A-Z0-9_]*$/u.test(name)) lines.push("          " + name + ": " + scalar(value));
  }
  return lines.join("\n") + "\n";
}
